const payload = $input.first().json;
const transaction = payload.transaction || {};
const completion_config = payload.configuration?.completion || {};
const completion_state = completion_config.completion_state || 'completed';
const fulfillment = payload.fulfillment_context || {};

let result_success = true;
let result_outcome = 'action_completed';
let new_status = 'completed';
let error = null;

function validateCompletionState(current_status, completion_state, fulfillment_mode) {
  const valid_transitions = {
    'completed': ['payment_confirmed', 'invoiced', 'awaiting_shipment', 'ready_for_pickup', 'digital_delivery_ready'],
    'picked_up': ['ready_for_pickup'],
    'delivered': ['awaiting_shipment']
  };

  const allowed = valid_transitions[completion_state] || [];
  return allowed.includes(current_status);
}

function canCompleteTransaction(completion_state, fulfillment_mode, current_status) {
  if (completion_state === 'picked_up') {
    return fulfillment_mode === 'store_pickup' && current_status === 'ready_for_pickup';
  } else if (completion_state === 'delivered') {
    return fulfillment_mode === 'home_delivery' && current_status === 'awaiting_shipment';
  } else if (completion_state === 'completed') {
    return validateCompletionState(current_status, completion_state, fulfillment_mode);
  }
  return false;
}

const can_complete = canCompleteTransaction(completion_state, fulfillment.mode, transaction.status);

if (!can_complete) {
  result_success = false;
  result_outcome = 'action_failed';
  new_status = 'completion_blocked';
  error = {
    code: 'TRANSACTION_NOT_READY_FOR_COMPLETION',
    category: 'business_rule',
    message: `Transaction cannot be completed. Current status: ${transaction.status}, required state: ${completion_state}`,
    retryable: false,
    details: {
      current_status: transaction.status,
      required_completion_state: completion_state,
      fulfillment_mode: fulfillment.mode
    }
  };
}

if (result_success) {
  if (completion_state === 'picked_up') {
    new_status = 'picked_up';
  } else if (completion_state === 'delivered') {
    new_status = 'delivered';
  }
}

const completion_data = result_success ? {
  completion_state: completion_state,
  final_status: new_status,
  completed_at: new Date().toISOString(),
  completion_verified: true,
  fulfillment_mode: fulfillment.mode || null,
  summary: {
    transaction_id: transaction.id,
    customer_id: payload.customer?.customer_id || null,
    total_amount: payload.commercial_context?.total || 0,
    currency: payload.commercial_context?.currency || 'COP',
    items_count: (payload.items || []).length,
    fulfillment_method: fulfillment.mode || 'unknown'
  }
} : null;

return [{
  json: {
    result: {
      success: result_success,
      outcome: result_outcome
    },
    transaction: {
      transaction_id: transaction.id,
      previous_status: transaction.status,
      current_status: new_status,
      sub_status: null,
      next_action: result_success ? null : 'handle_error'
    },
    route: {
      selected_flow: 'DALIA_M5_Commerce_Orchestrator',
      effective_action: 'complete_transaction',
      reason: result_success ? 'transaction_completion_finalized' : 'completion_preconditions_not_met'
    },
    response: {
      message_required: false,
      message_type: null,
      reply_text: null,
      requested_fields: []
    },
    data: {
      completion: completion_data || {}
    },
    error: error,
    trace: {
      trace_id: payload.trace?.trace_id || null,
      request_id: payload.trace?.request_id || null,
      workflow: 'DALIA_M5_06_Completion',
      stage: 'transaction_completion_finalized',
      processed_at: new Date().toISOString()
    }
  }
}];
